import base64
import json

# Simulando o recebimento do JSON (pode vir de um requests.get, por exemplo)
json_data = '''{
    "Content": "",
    "Format": "pdf",
    "Identity": "122c5533-ca1b-4eee-8f5f-a695fe52fd0f",
    "Name": "Extrato de pagamento",
    "HasItems": true
}'''

# Converte a string JSON para um dicionário Python
data = json.loads(json_data)

def gerar_pdf(dados):
    # Decodifica a string base64 para bytes
    pdf_bytes = base64.b64decode(dados['Content'])
    
    # Monta o nome do arquivo
    file_name = f"{dados['Name']}.{dados['Format']}"
    
    # Cria o arquivo em modo de escrita binária ('wb')
    with open(file_name, 'wb') as f:
        f.write(pdf_bytes)
        
    print(f"Arquivo '{file_name}' gerado com sucesso!")

gerar_pdf(data)